def test_three_steps():
    g = solution.discounted_returns([0.0, 1.0, 1.0], 0.9)
    assert abs(g[0] - 1.71) < 1e-9
    assert abs(g[1] - 1.9) < 1e-9
    assert abs(g[2] - 1.0) < 1e-9

def test_single():
    assert solution.discounted_returns([5.0], 0.9) == [5.0]

def test_gamma_zero():
    assert solution.discounted_returns([1, 2], 0.0) == [1.0, 2.0]

def test_empty():
    assert solution.discounted_returns([], 0.9) == []

def test_invalid_gamma():
    try:
        solution.discounted_returns([1.0], -0.1)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_gamma_one():
    assert solution.discounted_returns([1, 1, 1], 1.0) == [3.0, 2.0, 1.0]
